-- Apply: supabase db query --linked -f supabase/fs-grants-icecream-2026-11-01.sql
begin;
select count(*) as before_total from fs_grant_deadlines;

insert into fs_grant_deadlines (funder, program, kind, deadline_date, opens_date, amount, verified, url, notes, verified_on, level, project, priority, eligibility, match_required, status, gates, next_step, next_step_due)
select * from (values
('Urban Luxe Cafe (South Shore)','Local partner: ice cream donation or dine-and-donate','relationship',null::date,null::date,'in-kind or percent of sales',false,null,'UNVERIFIED research note: cafe at 2911 E 79th St, South Shore; premium hand-packed ice cream; says it supports budding artists and has an artist scholarship fund; hosts open mics. Ask: ice cream for the first summer sessions or a joint fundraiser night. Visit or call in person. Confirm the address, hours and the stated mission on their own page first.','2026-11-01'::date,'corporate','wednesdays',2,'Local business; unknown',null,'to_research','{}'::text[],'Verify the cafe and its giving mission, then visit in person with a one-page brief',null::date),
('Mitchell''s Ice Cream','Product donation or showcase sponsorship','relationship',null,null,'in-kind',false,null,'UNVERIFIED research note: founded 1931 on 71st St in South Shore (historic roots near your office); supplies hotels and restaurants. Contact listed: mitchellsicecream@viziamail.com, (708) 799-3835: confirm both on the company site before using. Ask for ice cream for events or a showcase sponsorship.','2026-11-01'::date,'corporate','wednesdays',2,'Unknown',null,'to_research','{}'::text[],'Verify the company and a current donation contact, then send a short in-kind request',null),
('The Original Rainbow Cone','Community partnership / Summer pop-up tour','relationship',null,null,'in-kind or truck visit',false,'https://www.rainbowcone.com/','UNVERIFIED research note: South Side institution that partners with community youth events; a Centennial Summer Surprise Tour of pop-up trucks was reported. Check RainbowCone.com and social media for tour stops and a contact form. Ask for a stop at a Tuesday session or a Rainbow Wednesday, or treats. Name fits the Rainbow Wednesdays color theme.','2026-11-01'::date,'corporate','wednesdays',2,'Unknown',null,'to_research','{}'::text[],'Check their site for a community or event request form; pitch a Rainbow Wednesday stop',null),
('Pretty Cool Ice Cream','Monthly community-support pop ($1 per pop)','rolling',null,null,'$1 per pop sold that month (reported)',false,null,'UNVERIFIED research note: Chicago ice cream maker (shop at 2353 N California Ave) that reportedly picks a community-support pop each month and gives $1 per pop to a local organization; has supported CPS literacy. Ask to be a summer community partner or for a donation for the 2027 kickoff. Use the website contact form.','2026-11-01'::date,'corporate','djclass',3,'Unknown',null,'to_research','{}'::text[],'Verify the program on their site; submit the contact form pitch',null),
('Carvel','Donation program (via TheShareWay)','rolling',null,null,'gift cards, coupons, product',false,null,'UNVERIFIED research note: Carvel donation requests through the TheShareWay platform (about 10 minutes) listing Illinois. Ask for gift cards or coupons as student rewards and volunteer thank-yous. Likely needs an account on TheShareWay: Stephen creates it.','2026-11-01'::date,'corporate','djclass',3,'Unknown; 501(c)(3) likely',null,'to_research','{g0}'::text[],'Confirm Carvel on TheShareWay; Stephen creates the account; then Claude fills the request',null),
('The Outside Scoop','Donation program (via TheShareWay)','rolling',null,null,'ice cream, gift cards, truck for events',false,null,'UNVERIFIED research note: donates ice cream for events, gift cards and discounted products; prefers 501(c)(3); also runs ice cream trucks for events; apply via TheShareWay (needs an account). Ask for a truck at a Rainbow Wednesday or the May 18 showcase.','2026-11-01'::date,'corporate','wednesdays',3,'501(c)(3) preferred',null,'to_research','{g0}'::text[],'Confirm on TheShareWay; same account as Carvel',null),
('Sweet Memories Ice Cream','Truck sponsorship or discounted event rate','relationship',null,null,'sponsorship or discount',false,null,'UNVERIFIED research note: family-owned Chicago Good Humor-style trucks since 1976; says it sponsors good causes and special events. Reach through its website or Roaming Hunger profile. Ask for a sponsored visit at a Rainbow Wednesday or a discounted 2-hour appearance for the May 18 showcase.','2026-11-01'::date,'corporate','wednesdays',3,'Unknown',null,'to_research','{}'::text[],'Find the real contact on their site; request a truck for one event',null),
('Jeni''s Splendid Ice Creams','Ice cream social sponsorship idea','relationship',null,null,'in-kind',false,null,'UNVERIFIED research note: reportedly partners with the Chicago Public Library Foundation on ice cream socials. Low confidence; check their community or sponsorship page before pitching. Kilwins (Arlington Heights, $1 per quart Month of Giving) is only a pitch model: ask a South Shore shop to copy it for July, do not ask Kilwins.','2026-11-01'::date,'corporate','wednesdays',3,'Unknown',null,'to_research','{}'::text[],'Low priority: verify before any outreach',null)
) as v(funder,program,kind,deadline_date,opens_date,amount,verified,url,notes,verified_on,level,project,priority,eligibility,match_required,status,gates,next_step,next_step_due)
where not exists (select 1 from fs_grant_deadlines g where g.funder = v.funder and g.program = v.program);

select count(*) as after_total from fs_grant_deadlines;
commit;
